#!/usr/bin/env bash
# Adds Items & Tools management to the instance detail page, built into
# the existing page alongside Connection (not a separate top-level
# section, per design).
#
# NEW: a lightweight equipment registry per kiosk instance — items and
# tools (e.g. barcode scanner, receipt printer, card reader) with:
#   - Add / edit / remove from the instance page directly.
#   - CSV export/import (columns: kind,name,description,serial_number,status).
#     Import is ADDITIVE — never removes or overwrites existing rows.
#   - JSON backup/restore. Restore is also ADDITIVE for the same reason:
#     a restore should never be able to silently wipe out equipment added
#     since the backup was taken.
#
# NOTE: this push writes the CURRENT app/models.py and
# app/blueprints/instances.py, which also include everything from the
# earlier Kiosk Process recode and PIN security pushes (same files, same
# repo, cumulative) — running this after those is fine and expected, not
# a conflict or a re-do.
#
# Run from inside /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

for req in app migrations requirements.txt run.py; do
    if [ ! -e "$req" ]; then
        echo "Error: expected to find '$req' here - run this from the admin_panel repo root."
        exit 1
    fi
done

TS="$(date +%Y%m%d_%H%M%S)"
mkdir -p "backups/$TS/templates/instances"
cp app/models.py "backups/$TS/models.py.bak" 2>/dev/null || true
cp app/blueprints/instances.py "backups/$TS/instances.py.bak" 2>/dev/null || true
cp app/templates/instances/detail.html "backups/$TS/templates/instances/detail.html.bak" 2>/dev/null || true
cp -r admin_panel.db "backups/$TS/admin_panel.db.bak" 2>/dev/null || true
echo "==> Backed up existing files (incl. a DB copy - this push includes a migration) to backups/$TS/"

echo "==> Writing app/models.py"
base64 -d > app/models.py << 'MODELS_PY_B64'

MODELS_PY_B64

echo "==> Writing app/blueprints/instances.py"
base64 -d > app/blueprints/instances.py << 'INSTANCES_PY_B64'

INSTANCES_PY_B64

echo "==> Writing app/templates/instances/detail.html"
base64 -d > app/templates/instances/detail.html << 'DETAIL_HTML_B64'

DETAIL_HTML_B64

echo "==> Writing new Alembic migration (instance_equipment_items)"
base64 -d > migrations/versions/7c2e91a4f3b8_add_instance_equipment_items.py << 'MIGRATION_PY_B64'

MIGRATION_PY_B64

echo "==> Verifying"
python3 -c "import ast; ast.parse(open('app/models.py').read())"
python3 -c "import ast; ast.parse(open('app/blueprints/instances.py').read())"
python3 -c "import ast; ast.parse(open('migrations/versions/7c2e91a4f3b8_add_instance_equipment_items.py').read())"
echo "    all Python files: syntax OK"

echo ""
echo "==> Applying database migration (instance_equipment_items table)"
source venv/bin/activate
FLASK_APP=run.py python -m flask db upgrade

echo ""
echo "==> Restarting the admin panel app"
pkill -f "admin_panel/run.py" 2>/dev/null || true
fuser -k 6090/tcp 2>/dev/null || true
sleep 1
nohup python run.py > app.log 2>&1 &
disown
sleep 2
tail -n 15 app.log

echo ""
echo "==================================================================="
echo "Items & Tools live. On any instance's page, right below Connection:"
echo "  - Add / edit / remove equipment (owner/administrator/manager)."
echo "  - Export CSV, Import CSV (additive)."
echo "  - Backup JSON, Restore from backup (additive)."
echo "==================================================================="
